type Work=Record<string,number>;
const knownCollectionRoutes=new Set([...collectionRoutes,...previewRoutes].map(path=>path?`/${path}`:"/"));
type Pal={i:number;id:string;dex:number;variant:boolean;names:Record<Locale,string>;power:number;rarity:number;size:string;nocturnal:boolean;hp:number;attack:number;defense:number;work:Work;guaranteedPassiveIds:string[];image?:boolean};
type PalData={meta:{gameBuild:string;sourceDbVersion:string;palCount:number;breedingCount:number;localIdMatchCount:number};pals:Pal[];pairs:BreedingRow[]};
