const app=document.querySelector<HTMLDivElement>("#app")!;
let locale=resolveLocale(location.pathname),m=messages(locale),data:PalData|null=null,itemData:ItemData|null=null,mapData:MapData|null=null,skillData:SkillData|null=null,itemLoading=false,palLoading=false,mapLoading=false,skillLoading=false;
const mapView={scale:1,x:0,y:0};
