const esc=(v:string)=>v.replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]!));
const route=()=>{const p=location.pathname.split("/").filter(Boolean);return locales.includes(p[0] as Locale)?`/${p.slice(1).join("/")}`.replace(/\/$/,"")||"/":"/"};
const href=(p:string)=>localizePath(locale,p);
