const skillLabels:Record<Locale,{title:string;active:string;passive:string;elements:string;all:string;power:string;cooldown:string;inherit:string;search:string}>={
  "en-US":{title:"Skills",active:"Active skills",passive:"Passive skills",elements:"Elements",all:"All",power:"Power",cooldown:"Cooldown",inherit:"Inheritable",search:"Search skills"},"ko-KR":{title:"스킬",active:"액티브 스킬",passive:"패시브 스킬",elements:"속성",all:"전체",power:"위력",cooldown:"쿨타임",inherit:"유전 가능",search:"스킬 검색"},"ja-JP":{title:"スキル",active:"アクティブスキル",passive:"パッシブスキル",elements:"属性",all:"すべて",power:"威力",cooldown:"クールタイム",inherit:"継承可能",search:"スキル検索"},"zh-CN":{title:"技能",active:"主动技能",passive:"被动技能",elements:"属性",all:"全部",power:"威力",cooldown:"冷却",inherit:"可继承",search:"搜索技能"},"zh-TW":{title:"技能",active:"主動技能",passive:"被動技能",elements:"屬性",all:"全部",power:"威力",cooldown:"冷卻",inherit:"可繼承",search:"搜尋技能"},"de-DE":{title:"Fähigkeiten",active:"Aktive Fähigkeiten",passive:"Passive Fähigkeiten",elements:"Elemente",all:"Alle",power:"Stärke",cooldown:"Abklingzeit",inherit:"Vererbbar",search:"Fähigkeiten suchen"},"fr-FR":{title:"Compétences",active:"Compétences actives",passive:"Compétences passives",elements:"Éléments",all:"Tout",power:"Puissance",cooldown:"Recharge",inherit:"Héréditaire",search:"Rechercher"},"it-IT":{title:"Abilità",active:"Abilità attive",passive:"Abilità passive",elements:"Elementi",all:"Tutte",power:"Potenza",cooldown:"Ricarica",inherit:"Ereditabile",search:"Cerca abilità"},"es-ES":{title:"Habilidades",active:"Habilidades activas",passive:"Habilidades pasivas",elements:"Elementos",all:"Todo",power:"Potencia",cooldown:"Recarga",inherit:"Heredable",search:"Buscar habilidades"},"es-419":{title:"Habilidades",active:"Habilidades activas",passive:"Habilidades pasivas",elements:"Elementos",all:"Todas",power:"Poder",cooldown:"Recarga",inherit:"Heredable",search:"Buscar habilidades"},"pt-BR":{title:"Habilidades",active:"Habilidades ativas",passive:"Habilidades passivas",elements:"Elementos",all:"Todas",power:"Poder",cooldown:"Recarga",inherit:"Herdável",search:"Buscar habilidades"},"ru-RU":{title:"Навыки",active:"Активные навыки",passive:"Пассивные навыки",elements:"Стихии",all:"Все",power:"Мощность",cooldown:"Перезарядка",inherit:"Наследуется",search:"Поиск навыков"},"id-ID":{title:"Skill",active:"Skill aktif",passive:"Skill pasif",elements:"Elemen",all:"Semua",power:"Kekuatan",cooldown:"Waktu tunggu",inherit:"Dapat diwariskan",search:"Cari skill"},"th-TH":{title:"สกิล",active:"สกิลใช้งาน",passive:"สกิลติดตัว",elements:"ธาตุ",all:"ทั้งหมด",power:"พลัง",cooldown:"คูลดาวน์",inherit:"สืบทอดได้",search:"ค้นหาสกิล"},"tr-TR":{title:"Beceriler",active:"Aktif beceriler",passive:"Pasif beceriler",elements:"Elementler",all:"Tümü",power:"Güç",cooldown:"Bekleme",inherit:"Kalıtılabilir",search:"Beceri ara"},"vi-VN":{title:"Kỹ năng",active:"Kỹ năng chủ động",passive:"Kỹ năng bị động",elements:"Hệ",all:"Tất cả",power:"Sức mạnh",cooldown:"Hồi chiêu",inherit:"Có thể di truyền",search:"Tìm kỹ năng"},"pl-PL":{title:"Umiejętności",active:"Umiejętności aktywne",passive:"Umiejętności pasywne",elements:"Żywioły",all:"Wszystkie",power:"Moc",cooldown:"Odnowienie",inherit:"Dziedziczna",search:"Szukaj umiejętności"}
};
const partnerLabel:Record<Locale,string>={"en-US":"Partner skills","ko-KR":"파트너 스킬","ja-JP":"パートナースキル","zh-CN":"伙伴技能","zh-TW":"夥伴技能","de-DE":"Partnerfähigkeiten","fr-FR":"Compétences partenaire","it-IT":"Abilità partner","es-ES":"Habilidades de compañero","es-419":"Habilidades de compañero","pt-BR":"Habilidades de parceiro","ru-RU":"Навыки напарника","id-ID":"Skill partner","th-TH":"สกิลคู่หู","tr-TR":"Ortak becerileri","vi-VN":"Kỹ năng đồng hành","pl-PL":"Umiejętności partnera"};
function skillTabs(activeKind=""){const labels=skillLabels[locale],tabs:[string,string][]=[["",labels.all],["active",labels.active],["passive",labels.passive],["partner",partnerLabel[locale]]];return `<nav class="subnav" aria-label="${labels.title}">${tabs.map(([kind,label])=>`<a href="${href(kind?`/skills/${kind}`:"/skills")}" data-link class="${activeKind===kind?"active":""}">${label}</a>`).join("")}</nav>`}
function skillsCategoryPage(kind:"active"|"passive"|"partner"){if(kind==="partner"){const localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale],skills=skillData?.partnerSkills||[],pals=new Map(data?.pals.map(p=>[p.id,p])||[]);setMeta(partnerLabel[locale],partnerLabel[locale]);return `${hero(partnerLabel[locale],partnerLabel[locale])}<section class="section">${skillTabs(kind)}<div class="skill-grid">${skills.map(skill=>{const pal=pals.get(skill.palId);return `<article class="skill-card"><div class="skill-card-head">${pal?.image?`<img src="/assets/pals/${encodeURIComponent(pal.id)}.png" alt="" width="56" height="56" loading="lazy">`:""}<div><h2><a href="${href(`/skills/partner/${encodeURIComponent(skill.id)}`)}" data-link>${esc(localized(skill.names)||palName(pal!))}</a></h2>${pal?`<a href="${href(`/pals/${encodeURIComponent(pal.id)}`)}" data-link>${esc(palName(pal))}</a>`:""}</div></div></article>`}).join("")}</div></section>`}const html=skillsPage(),labels=skillLabels[locale];setMeta(kind==="active"?labels.active:labels.passive,`${labels.active} · ${labels.passive}`);return `<div class="skill-category-${kind}">${html.replace('<section class="section">',`<section class="section">${skillTabs(kind)}`)}</div>`}

function setMeta(title:string,description=m.tagline){document.documentElement.lang=locale;document.title=`${title} · ${site.name}`;document.querySelectorAll("[data-dynamic-meta]").forEach(n=>n.remove());const canonical=`${site.origin}${href(route())}`;for(const [tag,attrs] of [["meta",{name:"description",content:description}],["link",{rel:"canonical",href:canonical}],["meta",{property:"og:title",content:document.title}],["meta",{property:"og:description",content:description}],["meta",{property:"og:url",content:canonical}],["meta",{name:"twitter:card",content:"summary"}]] as const){const el=document.createElement(tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));el.setAttribute("data-dynamic-meta","true");document.head.append(el)}for(const loc of locales){const el=document.createElement("link");el.rel="alternate";el.hreflang=loc;el.href=`${site.origin}${localizePath(loc,route())}`;el.dataset.dynamicMeta="true";document.head.append(el)}const alternate=document.createElement("link");alternate.rel="alternate";alternate.hreflang="x-default";alternate.href=`${site.origin}${localizePath(defaultLocale,route())}`;alternate.dataset.dynamicMeta="true";document.head.append(alternate)}
function header(){const nav:{label:string;path:string}[]=[[m.home,"/"],[m.map,"/map"],[m.pals,"/pals"],[skillLabels[locale].title,"/skills"],[m.calculators,"/calculators/breeding"],[m.database,"/database"],[m.server,"/server-tools/settings-generator"]].map(([label,path])=>({label,path}));return `<header class="site-header"><a class="brand" href="${href("/")}" data-link><span class="brand-mark">P</span><span>${site.name}</span></a><nav aria-label="${m.home}">${nav.map(({label,path})=>`<a href="${href(path)}" data-link class="${route()===path?"active":""}">${label}</a>`).join("")}</nav><div class="header-actions"><select id="locale" aria-label="${m.language}">${locales.map(l=>`<option value="${l}" ${l===locale?"selected":""}>${localeLabels[l]}</option>`).join("")}</select><button class="icon-button" id="theme" aria-label="${m.theme}">◐</button></div></header>`}
function footer(){return `<footer><div><strong>${site.name}</strong><p>${m.footer}</p></div></footer>`}
function consentBanner(){if(!(site.analyticsId||site.adsenseClient)||localStorage.getItem("pw-consent"))return "";return `<aside class="consent" aria-label="${m.consentTitle}"><div><strong>${m.consentTitle}</strong><p>${m.consentBody}</p></div><button class="button primary" data-consent="allow">${m.allow}</button><button class="button" data-consent="decline">${m.decline}</button></aside>`}
function hero(title:string,body:string){return `<section class="page-hero"><p class="eyebrow">${m.verified}</p><h1>${title}</h1><p>${body}</p></section>`}
function home(){setMeta(m.home);return `<section class="hero"><div class="hero-copy"><p class="eyebrow">${m.verified}</p><h1>${m.hero}</h1><p class="lede">${m.tagline}</p><div class="hero-actions"><a class="button primary" href="${href("/pals")}" data-link>${m.openPals}</a><a class="button" href="${href("/calculators/breeding")}" data-link>${m.openBreed}</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbital one"></div><div class="orbital two"></div><div class="island i1"></div><div class="island i2"></div></div></section><section class="section">${site.adsenseClient&&site.adsenseContentSlot?`<div class="ad-slot" aria-label="${m.adReserved}" data-ad-slot="${esc(site.adsenseContentSlot)}">${m.adReserved}</div>`:""}</section>`}
function palCard(p:Pal){const work=Object.entries(p.work).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,4),search=[...Object.values(p.names),p.id,p.dex,...Object.keys(p.work).filter(k=>p.work[k]>0)].join(" ").toLocaleLowerCase(locale);return `<article class="pal-card" data-pal="${esc(search)}" data-rarity="${p.rarity}" data-work="${esc(Object.keys(p.work).filter(k=>p.work[k]>0).join(" "))}">${p.image?`<img class="entity-image pal-image" src="/assets/pals/${encodeURIComponent(p.id)}.png" alt="${esc(palName(p))}" loading="lazy" width="160" height="160">`:`<div class="pal-image item-fallback" aria-hidden="true">◇</div>`}<div class="pal-card-body"><div class="pal-number">#${p.dex}${p.variant?"B":""}</div><h2><a href="${href(`/pals/${encodeURIComponent(p.id)}`)}" data-link>${esc(palName(p))}</a></h2><code>${esc(p.id)}</code><dl class="pal-stats"><div><dt>${m.hp}</dt><dd>${p.hp}</dd></div><div><dt>${m.attack}</dt><dd>${p.attack}</dd></div><div><dt>${m.defense}</dt><dd>${p.defense}</dd></div><div><dt>${m.rarity}</dt><dd>${p.rarity}</dd></div></dl><p class="work-tags">${work.map(([k,v])=>`<span>${k} ${v}</span>`).join("")}</p></div></article>`}
function palsPage(){setMeta(m.pals,m.palDexBody);const pals=[...(data?.pals||[])],sorted=pals.sort((a,b)=>a.dex-b.dex||Number(a.variant)-Number(b.variant)||a.id.localeCompare(b.id)),rarities=[...new Set(pals.map(p=>p.rarity))].sort((a,b)=>a-b),works=[...new Set(pals.flatMap(p=>Object.keys(p.work).filter(k=>p.work[k]>0)))].sort();return `${hero(m.palDex,m.palDexBody)}<section class="section"><div class="collection-filters"><label class="collection-search">${m.search}<input id="pal-search" type="search" autocomplete="off"></label><label>${m.rarity}<select id="pal-rarity"><option value="">${m.choose}</option>${rarities.map(v=>`<option value="${v}">${v}</option>`).join("")}</select></label><label>${m.work}<select id="pal-work"><option value="">${m.choose}</option>${works.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join("")}</select></label><button class="button search-clear" data-clear-search="pal" aria-label="${m.remove}">×</button></div><p id="pal-count" role="status">${sorted.length.toLocaleString(locale)} ${m.results}</p><p id="pal-empty" class="empty-compact" hidden>${m.noResult}</p><div class="pal-grid">${sorted.map(palCard).join("")}</div></section>`}
function itemCard(item:Item){const search=[...Object.values(item.names),item.id,item.type,item.subtype].join(" ").toLocaleLowerCase(locale);return `<article class="item-card" data-item="${esc(search)}" data-type="${esc(item.type)}" data-rarity="${item.rarity}"><div class="item-card-head">${item.image?`<img class="entity-image item-image" src="/assets/items/${encodeURIComponent(item.id)}.webp" alt="${esc(itemName(item))}" loading="lazy" width="96" height="96">`:`<span class="item-image item-fallback" aria-hidden="true">◇</span>`}<div><h2><a href="${href(`/items/${encodeURIComponent(item.id)}`)}" data-link>${esc(itemName(item))}</a></h2><code>${esc(item.id)}</code></div></div><p class="work-tags"><span>${esc(item.type)}</span><span>${esc(item.subtype)}</span></p><dl class="item-stats"><div><dt>${m.rank}</dt><dd>${item.rank}</dd></div><div><dt>${m.rarity}</dt><dd>${item.rarity}</dd></div><div><dt>${m.stack}</dt><dd>${item.maxStack.toLocaleString(locale)}</dd></div><div><dt>${m.weight}</dt><dd>${item.weight.toLocaleString(locale)}</dd></div><div><dt>${m.price}</dt><dd>${item.price.toLocaleString(locale)}</dd></div></dl></article>`}
function databasePage(){setMeta(m.itemDatabase,m.itemDatabaseBody);const items=[...(itemData?.items||[])],sorted=items.sort((a,b)=>new Intl.Collator(locale,{numeric:true}).compare(itemName(a),itemName(b))||a.id.localeCompare(b.id)),types=[...new Set(items.map(i=>i.type))].sort(),rarities=[...new Set(items.map(i=>i.rarity))].sort((a,b)=>a-b);return `${hero(m.itemDatabase,m.itemDatabaseBody)}<section class="section"><p><a class="button primary" href="${href("/calculators/crafting")}" data-link>${m.openCrafting}</a></p><div class="collection-filters"><label class="collection-search">${m.searchItems}<input id="item-search" type="search" autocomplete="off"></label><label>Type<select id="item-type"><option value="">${m.choose}</option>${types.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join("")}</select></label><label>${m.rarity}<select id="item-rarity"><option value="">${m.choose}</option>${rarities.map(v=>`<option value="${v}">${v}</option>`).join("")}</select></label><button class="button search-clear" data-clear-search="item" aria-label="${m.remove}">×</button></div><p id="item-count" role="status">${sorted.length.toLocaleString(locale)} ${m.results}</p><p id="item-empty" class="empty-compact" hidden>${m.noResult}</p><div class="item-grid">${sorted.map(itemCard).join("")}</div></section>`}
function skillsPage(){const labels=skillLabels[locale],localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale],elements=skillData?.elements||[],active=skillData?.activeSkills||[],passive=skillData?.passiveSkills||[];setMeta(labels.title,`${labels.active} · ${labels.passive}`);const elementById=new Map(elements.map(element=>[element.id,element]));const activeCards=active.map(skill=>{const element=elementById.get(skill.elementId),search=[skill.id,skill.elementId,...Object.values(skill.names),...(element?Object.values(element.names):[])].join(" ").toLocaleLowerCase(locale);return `<article class="skill-card" data-skill="${esc(search)}" data-kind="active" data-element="${esc(skill.elementId)}"><div class="skill-card-head"><img src="${esc(element?.icon||`/assets/elements/${skill.elementId}.svg`)}" alt="${esc(element?localized(element.names):skill.elementId)}" width="56" height="56"><div><h2><a href="${href(`/skills/active/${encodeURIComponent(skill.id)}`)}" data-link>${esc(localized(skill.names))}</a></h2><code>${esc(skill.id)}</code></div></div><p class="work-tags"><span>${esc(element?localized(element.names):skill.elementId)}</span><span>${labels.power} ${skill.power}</span><span>${labels.cooldown} ${skill.cooldown}</span>${skill.canInherit?`<span>${labels.inherit}</span>`:""}</p></article>`}).join("");const passiveCards=passive.map(skill=>{const search=[skill.id,...Object.values(skill.names),...Object.values(skill.descriptions)].join(" ").toLocaleLowerCase(locale);return `<article class="skill-card passive-skill" data-skill="${esc(search)}" data-kind="passive" data-element=""><div class="skill-card-head"><span class="passive-rank" aria-hidden="true">${skill.rank>=0?"+":""}${skill.rank}</span><div><h2><a href="${href(`/skills/passive/${encodeURIComponent(skill.id)}`)}" data-link>${esc(localized(skill.names))}</a></h2><code>${esc(skill.id)}</code></div></div><p>${esc(localized(skill.descriptions))}</p><p class="work-tags">${skill.randomInheritanceAllowed?`<span>${labels.inherit}</span>`:""}</p></article>`}).join("");return `${hero(labels.title,`${labels.active} · ${labels.passive}`)}<section class="section"><div class="element-strip" aria-label="${labels.elements}">${elements.map(element=>`<button type="button" data-element-button="${esc(element.id)}"><img src="${esc(element.icon)}" alt="" width="40" height="40"><span>${esc(localized(element.names))}</span></button>`).join("")}</div><div class="collection-filters"><label class="collection-search">${labels.search}<input id="skill-search" type="search" autocomplete="off"></label><label>${labels.title}<select id="skill-kind"><option value="">${labels.all}</option><option value="active">${labels.active}</option><option value="passive">${labels.passive}</option></select></label><label>${labels.elements}<select id="skill-element"><option value="">${labels.all}</option>${elements.map(element=>`<option value="${esc(element.id)}">${esc(localized(element.names))}</option>`).join("")}</select></label><button class="button search-clear" data-clear-search="skill" aria-label="${m.remove}">×</button></div><p id="skill-count" role="status">${(active.length+passive.length).toLocaleString(locale)} ${m.results}</p><p id="skill-empty" class="empty-compact" hidden>${m.noResult}</p><div class="skill-grid">${activeCards}${passiveCards}</div></section>`}
function skillDetail(kind:string,id:string){const labels=skillLabels[locale],localized=(names:Record<Locale,string>)=>names[locale]||names[defaultLocale];if(kind==="active"){const skill=skillData?.activeSkills.find(entry=>entry.id===id),element=skillData?.elements.find(entry=>entry.id===skill?.elementId);if(!skill)return placeholder("404");setMeta(localized(skill.names),labels.active);return `${hero(localized(skill.names),labels.active)}<article class="entity-detail panel"><img class="detail-image element-detail" src="${esc(element?.icon||"")}" alt="${esc(element?localized(element.names):skill.elementId)}"><div><code>${esc(skill.id)}</code><dl class="detail-stats"><div><dt>${labels.elements}</dt><dd>${esc(element?localized(element.names):skill.elementId)}</dd></div><div><dt>${labels.power}</dt><dd>${skill.power}</dd></div><div><dt>${labels.cooldown}</dt><dd>${skill.cooldown}</dd></div><div><dt>${labels.inherit}</dt><dd>${skill.canInherit?m.yes:m.no}</dd></div><div><dt>Skill Fruit</dt><dd>${skill.hasSkillFruit?m.yes:m.no}</dd></div></dl></div></article>`}const skill=skillData?.passiveSkills.find(entry=>entry.id===id);if(!skill)return placeholder("404");setMeta(localized(skill.names),labels.passive);return `${hero(localized(skill.names),labels.passive)}<article class="entity-detail panel"><span class="detail-image passive-rank">${skill.rank>=0?"+":""}${skill.rank}</span><div><code>${esc(skill.id)}</code><p>${esc(localized(skill.descriptions))}</p><dl class="detail-stats"><div><dt>${labels.inherit}</dt><dd>${skill.randomInheritanceAllowed?m.yes:m.no}</dd></div><div><dt>Surgery cost</dt><dd>${skill.surgeryCost.toLocaleString(locale)}</dd></div></dl></div></article>`}
