type AnalyticsParams=Record<string,string|number|boolean>;
function trackEvent(name:string,params:AnalyticsParams={}){if(localStorage.getItem("pw-consent")!=="granted")return;const win=window as Window&{gtag?:(...args:unknown[])=>void};win.gtag?.("event",name,params)}
